t = int(input())
ns = []
for i in range(t):
	n = int(input())
	arr = list(map(int, input().split()))
	ans = []
	sm = sum(arr)
	if sm % n != 0:
		ans = -1
	else:
		avg = sm // n
		for (idx, el) in enumerate(arr):
			if idx == 0:
				continue
			tru = idx + 1
			tmp1 = (1, tru, (tru - el % tru) % tru)
			tmp2 = (tru, 1, (el + tmp1[2]) // tru)
			ans.append(tmp1)
			ans.append(tmp2)
		for (idx, el) in enumerate(arr):
			if idx == 0:
				continue
			tru = idx + 1
			tmp3 = (1, tru, avg)
			ans.append(tmp3)
	ns.append(ans)
for el in ns:
	if el == -1:
		print(-1)
	else:
		print(len(el))
		for el1 in el:
			print(' '.join(list(map(str, el1))))
